namespace {unsigned checks{};void check(bool yes,std::source_location at=std::source_location::current()){++checks;if(!yes)throw std::runtime_error("Tom playback regression line "+std::to_string(at.line()));}std::vector<std::uint32_t> pixels(notes::Canvas& c){std::vector<std::uint32_t> out(1632*2160),paper(out.size(),0xffffffffu);c.composite({out,1620,2160,1632},paper,{0,0,1620,2160});return out;}unsigned dark(const std::vector<std::uint32_t>& p){unsigned n=0;for(auto v:p)if((v>>24)>230&&(v&0xffffffu)<0x606060u)++n;return n;}}
int main(int argc,char** argv){QCoreApplication app(argc,argv);try{QTemporaryDir temporary;temporary.setAutoRemove(false);check(temporary.isValid());{tom::Panel panel({},temporary.path().toStdString(),false);check(panel.outputMode()==tom::OutputMode::Handwritten);check(panel.finish(5000));}const auto request=product::newId(),document=product::newId(),note=product::newId(),groupId=product::newId();const auto pointerRoot=std::filesystem::path(temporary.path().toStdString());QJsonObject page{{"document",document},{"revision",QString(64,'a')}};check(tomnative::read(pointerRoot,request).isEmpty());tomnative::remember(pointerRoot,request,page,note,groupId);auto link=tomnative::read(pointerRoot,request);check(link.value("document")==document&&link.value("note")==note&&link.value("group")==groupId);check(tomnative::read(pointerRoot,product::newId()).isEmpty());auto index=pointerRoot/"tom-native-output"/(request.toStdString()+".json");auto invalid=link;invalid["unexpected"]=true;underlay::atomicFile(index,QJsonDocument(invalid).toJson(QJsonDocument::Compact));check(tomnative::read(pointerRoot,request).isEmpty());tomnative::remember(pointerRoot,request,page,note,groupId);check(tomnative::read(pointerRoot,request)==link);const auto wrong=product::newId();std::filesystem::create_symlink(index,pointerRoot/"tom-native-output"/(wrong.toStdString()+".json"));check(tomnative::read(pointerRoot,wrong).isEmpty());bool denied=false;try{tomnative::remember(pointerRoot,wrong,page,note,groupId);}catch(...){denied=true;}check(denied&&tomnative::read(pointerRoot,request)==link);const QString text="This passage is primarily about memory and loss.";tomink::HandwritingOptions options;auto group=tomink::handwriting(text,options);check(group.timing.size()==std::size_t(group.strokes.size()));unsigned words=0;for(auto t:group.timing){check(t.complexity>=1&&t.complexity<=4);words+=t.pauseAfterMs>=35;}check(words>=8);check(group.strokes.first().toObject()["style"].toObject()["color"]=="black");auto medium=options;medium.style["width"]="medium";auto reference=tomink::handwriting(text,medium);notes::Window window;const auto stronger=dark(notes::render(group.strokes,window)),older=dark(notes::render(reference.strokes,window));check(stronger>=older*1.3&&group.strokes.size()==reference.strokes.size()&&group.points==reference.points);auto canonical=QJsonDocument(group.strokes).toJson(QJsonDocument::Compact);auto plan=tomink::playbackPlan("short",group.strokes,group.timing);auto longGroup=tomink::handwriting(((text+" ").repeated(6)+"\n\n").repeated(3),options);auto longer=tomink::playbackPlan("long",longGroup.strokes,longGroup.timing);check(plan->durationMs>=3000&&plan->durationMs<=15000&&longer->durationMs>plan->durationMs&&longer->durationMs<=45000);check(longer->durationMs/plan->durationMs<18*.7);bool rejected=false;try{auto invalid=tomink::PlaybackConfig{};invalid.pixelsPerSecond=0;(void)tomink::playbackPlan("invalid",group.strokes,group.timing,invalid);}catch(...){rejected=true;}check(rejected);notes::Canvas canvas;canvas.install(window,notes::render({},window),0,0);tomink::StrokePlayback playback;playback.start(plan);auto start=std::chrono::steady_clock::now()+std::chrono::seconds(1);unsigned ticks=0;double completedMs=0;unsigned partial=0;std::vector<std::uint32_t> finished;for(unsigned elapsed=0;elapsed<=60000;elapsed+=40){if(playback.tick(canvas,start+std::chrono::milliseconds(elapsed)))++ticks;if(elapsed==560){check(playback.active());partial=dark(pixels(canvas));check(partial>0&&partial<stronger);}if(!playback.active()){completedMs=elapsed;finished=pixels(canvas);break;}canvas.clearDamage();}check(!finished.empty()&&completedMs>=3000&&completedMs<=15000&&ticks>20);check(canonical==QJsonDocument(group.strokes).toJson(QJsonDocument::Compact));notes::Canvas repeated;repeated.install(window,notes::render({},window),0,0);tomink::StrokePlayback again;again.start(tomink::playbackPlan("short",group.strokes,group.timing));for(unsigned elapsed=0;again.active()&&elapsed<=60000;elapsed+=40){again.tick(repeated,start+std::chrono::milliseconds(elapsed));repeated.clearDamage();}check(!again.active()&&pixels(repeated)==finished);notes::Canvas interrupted;interrupted.install(window,notes::render({},window),0,0);tomink::StrokePlayback paused;paused.start(plan);paused.tick(interrupted,start);paused.suspend(interrupted);auto before=pixels(interrupted);check(pixels(interrupted)==before&&paused.active());paused.tick(interrupted,start+std::chrono::seconds(60));check(paused.active()&&dark(pixels(interrupted))<stronger);paused.suspend(interrupted);interrupted.playEnd();paused.clear();check(!paused.active()&&canonical==QJsonDocument(group.strokes).toJson(QJsonDocument::Compact));notes::Canvas layered;layered.install(window,notes::render({},window),0,0);layered.preparePlayback(plan->bounds);tomink::StrokePlayback concurrent;concurrent.start(plan);concurrent.tick(layered,start);concurrent.suspend(layered);layered.enable(true);layered.setStyle({styled::Tool::Fineliner,styled::Width::Thick,7});const auto endPoint=plan->strokes.back().points.front();const int px=int(std::floor(endPoint.x))+window.area.x0,py=int(std::floor(endPoint.y))+window.area.y0-window.scroll;check(layered.reserve());for(auto phase:{spike::Phase::Down,spike::Phase::Up}){spike::Point p;p.x=px;p.y=py;p.phase=phase;check(layered.append(p));}unsigned slot;QJsonObject user;bool erased;check(layered.take(slot,user,erased)&&!erased);layered.acknowledge(slot,true);const auto userPixel=pixels(layered)[std::size_t(py)*1632+px];check(((userPixel>>16)&255)>(userPixel&255)+40);for(unsigned elapsed=40;concurrent.active()&&elapsed<=60000;elapsed+=40){concurrent.tick(layered,start+std::chrono::milliseconds(elapsed));layered.clearDamage();}check(!concurrent.active()&&pixels(layered)[std::size_t(py)*1632+px]==userPixel);std::printf("TOM_PLAYBACK_PASS checks=%u sentence_ms=%.0f planned_ms=%.3f long_ms=%.3f ticks=%u partial_pixels=%u dark_pixels=%u medium_pixels=%u native_default=true adaptive=true deterministic=true provider_calls=0 physical=NOT_RUN\n",checks,completedMs,plan->durationMs,longer->durationMs,ticks,partial,stronger,older);return 0;}catch(const std::exception& e){std::fprintf(stderr,"TOM_PLAYBACK_FAIL %s\n",e.what());return 1;}}
